insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('hero','{"en":"Web-development & business-analysis","uk":"Web-development & business-analysis"}','{"en":"Web solutions built around your business requirements","uk":"Web solutions built around your business requirements"}','{"en":"ONVORX helps B2B companies plan, build and grow websites and digital solutions — from formalizing requirements and implementation through to ongoing support.","uk":"ONVORX helps B2B companies plan, build and grow websites and digital solutions — from formalizing requirements and implementation through to ongoing support."}','{"en":"Request an Estimate","uk":"Request an Estimate"}');
insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('services','{"en":"Services","uk":"Services"}','{"en":"From requirements to implementation and ongoing development","uk":"From requirements to implementation and ongoing development"}','{"en":"ONVORX can join a project at different stages — from defining requirements and building a new website to developing an existing solution and supporting further growth.","uk":"ONVORX can join a project at different stages — from defining requirements and building a new website to developing an existing solution and supporting further growth."}',null);
insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('projects','{"en":"Selected projects","uk":"Selected projects"}','{"en":"Selected work in web development","uk":"Selected work in web development"}','{"en":"We build web solutions that solve real business challenges. Here are some of our recent projects.","uk":"We build web solutions that solve real business challenges. Here are some of our recent projects."}',null);
insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('howWork','{"en":"How we work","uk":"How we work"}','{"en":"A clear path from task to implementation","uk":"A clear path from task to implementation"}','{"en":"ONVORX can join a project at the stage where support is needed — from clarifying requirements to implementation and further development.","uk":"ONVORX can join a project at the stage where support is needed — from clarifying requirements to implementation and further development."}',null);
insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('about','{"en":"About ONVORX","uk":"About ONVORX"}','{"en":"Practical experience behind every project","uk":"Practical experience behind every project"}','{"en":"ONVORX combines hands-on web development experience with a structured approach to requirements, implementation and ongoing development.","uk":"ONVORX combines hands-on web development experience with a structured approach to requirements, implementation and ongoing development."}',null);
insert into public.site_sections (key,eyebrow,title,body,cta_label) values ('cta','{"en":"Start a project","uk":"Start a project"}','{"en":"Let’s turn your requirements into a working solution","uk":"Let’s turn your requirements into a working solution"}','{"en":"Tell us what you’re planning, what already exists and where support is needed. ONVORX will review the requirements and clarify what’s needed to prepare a project estimate.","uk":"Tell us what you’re planning, what already exists and where support is needed. ONVORX will review the requirements and clarify what’s needed to prepare a project estimate."}','{"en":"Request a Project Estimate","uk":"Request a Project Estimate"}');
